  "follow_up_queries": [
    {
      "reason": "Establish the correct loss formulation and distinguish evidence for sampled softmax from evidence for generalized BCE.",
      "query": "For SASRec next-item recommendation, how do uniform multiple-negative sampled softmax and gSASRec generalized BCE differ in calibration, sampling-probability correction, duplicate-negative handling, and exclusion of known training positives? What exact objectives and reproducible settings do gSASRec and eSASRec provide?"
    },
    {
      "reason": "Determine whether recent pooling adds useful information beyond SASRec and identify controls that isolate its contribution.",
      "query": "In sequential recommendation with SASRec, what evidence supports gated residual fusion of a causal last-three-item embedding mean? Which ablations distinguish recency benefits from extra LayerNorm, added parameters, or an ungated residual, and how should padding and residual initialization be handled?"
    },
    {
      "reason": "Resolve feasibility and selection reliability before spending the fixed search budget.",
      "query": "For SASRec trained with 128 negatives per sequence position, what PyTorch techniques compute exact sampled-softmax gradients with bounded memory, and how should fixed-budget ablations and paired uncertainty estimates be designed for HR@10 evaluated on 200 users per dataset with 99 fixed negatives, while limiting repeated-validation selection bias?"
    }
  ]
